"""Enumerate the uncovered lines and branch outcomes in the certified source.

coverage_union.py reports the figure. This reports the set behind it: every
line and every branch outcome the union leaves uncovered, with the function
that encloses it, the source text, and the build configurations that compile
it. That set is the input to the work that closes the gaps, and it has to be
the same set the published figure is the complement of, not a similar one
derived a second way.

So the keying is not reimplemented here. This imports union() from
coverage_union and filters what it already computed. A branch is keyed by
(file, line, branch count on that line, ordinal) rather than by position alone,
because three common/src lines compile to a different number of branches in
different configurations: each is a switch with a case under #if. A second
implementation of that key would be a second thing to get wrong, and a gap
listing that disagrees with the figure by one item puts two numbers in the
evidence with no way to tell which is the coverage.

The totals are printed first so that they can be checked against the figure
coverage_union.py printed for the same tracefiles before anything downstream
reads the listing. gcovr's merged report is not a substitute source: it keys
branches by gcov's block numbers, and on this tree it disagrees with the union
in both directions.

Which configurations compile an item is read from the tracefiles, not from the
preprocessor conditions: a line absent from a configuration's report was not
compiled there. For a branch outcome the form is part of that answer, so an
outcome on a line with two forms lists only the configurations that compile the
form it belongs to.

Usage: coverage_gaps.py <tracefile-dir> [--tsv]

<tracefile-dir> is read the way coverage_union.py reads it: the *.json files
directly inside it, one per configuration in the merge set. The informational
subdirectory coverage.sh writes is not part of the figure and is not read.
Source text is read relative to the repository root this script sits in.
"""

import collections
import glob
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from coverage_union import union, exclude_hook_sites, multiform_lines

REPO_ROOT = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", ".."))


def compiled_in(tracefiles):
    """Per (file, line) and per (file, line, form), the configurations compiling it.

    The form is the branch count the configuration compiled the line with; a
    line with no branches there has no form entry. Also returns gcovr's own
    attribution of each line to a function.
    """

    lines = collections.defaultdict(set)
    forms = collections.defaultdict(set)
    functions = {}
    for path in tracefiles:
        configuration = os.path.basename(path)[:-len(".json")]
        with open(path, encoding="utf-8") as handle:
            data = json.load(handle)
        for entry in data.get("files", []):
            name = entry["file"]
            for line in entry.get("lines", []):
                key = (name, line["line_number"])
                lines[key].add(configuration)
                if line.get("branches"):
                    forms[key + (len(line["branches"]),)].add(configuration)
                if line.get("function_name") and key not in functions:
                    functions[key] = line["function_name"]
    return lines, forms, functions


def source_line(cache, path, number):
    if path not in cache:
        try:
            with open(os.path.join(REPO_ROOT, path), encoding="utf-8", errors="replace") as handle:
                cache[path] = handle.read().splitlines()
        except OSError:
            cache[path] = []
    text = cache[path]
    return text[number - 1].strip() if 0 < number <= len(text) else ""


def main():
    if len(sys.argv) < 2:
        print("usage: coverage_gaps.py <tracefile-dir> [--tsv]", file=sys.stderr)
        return 2

    directory = sys.argv[1]
    as_tsv = "--tsv" in sys.argv[2:]

    tracefiles = sorted(glob.glob(os.path.join(directory, "*.json")))
    if not tracefiles:
        print("coverage_gaps.py: no JSON in %s." % directory, file=sys.stderr)
        return 1

    lines, branches, shapes, silent = union(tracefiles)
    if not lines:
        print("coverage_gaps.py: the tracefiles contain no files.", file=sys.stderr)
        return 1
    if silent:
        print("coverage_gaps.py: %d configuration(s) covered no certified line: %s"
              % (len(silent), ", ".join(silent)), file=sys.stderr)
        return 1

    # Same order as coverage_union.main: the key's soundness is established
    # before any set derived from it is reported.
    multiform = multiform_lines(shapes)
    excluded, missing = exclude_hook_sites(lines, branches)
    if missing:
        for path, number, macro in missing:
            print("coverage_gaps.py: %s:%d is not in the report -- %s has moved."
                  % (path, number, macro), file=sys.stderr)
        return 1

    uncovered_lines = sorted(key for key, hit in lines.items() if not hit)
    uncovered_branches = sorted(key for key, hit in branches.items() if not hit)
    configurations = [os.path.basename(p)[:-len(".json")] for p in tracefiles]
    multiform_keys = {(path, number): sorted(set(counts.values()))
                      for path, number, counts in multiform}

    if as_tsv:
        where, form_where, functions = compiled_in(tracefiles)
        cache = {}
        print("kind\tfile\tline\tforms\tordinal\tline_forms\tfunction\tn_configs\tconfigurations\tsource")
        rows = [("line", p, n, "", "") for p, n in uncovered_lines] + \
               [("branch", p, n, c, i) for p, n, c, i in uncovered_branches]
        for kind, path, number, count, index in sorted(rows, key=lambda r: (r[1], r[2], r[0] != "line", r[3], r[4])):
            if kind == "line":
                compiling = where[(path, number)]
            else:
                compiling = form_where[(path, number, count)]
            line_forms = "/".join(str(n) for n in multiform_keys.get((path, number), []))
            print("%s\t%s\t%d\t%s\t%s\t%s\t%s\t%d\t%s\t%s"
                  % (kind, path, number, count, index, line_forms,
                     functions.get((path, number), "?"), len(compiling),
                     ";".join(c for c in configurations if c in compiling),
                     source_line(cache, path, number).replace("\t", " ")))
        return 0

    covered_lines = len(lines) - len(uncovered_lines)
    covered_branches = len(branches) - len(uncovered_branches)
    print("coverage_gaps.py: unioned over %d configuration(s)" % len(tracefiles))
    print()
    print("    lines    %d uncovered of %d (%d covered)" % (len(uncovered_lines), len(lines), covered_lines))
    print("    branches %d uncovered of %d (%d covered)" % (len(uncovered_branches), len(branches), covered_branches))
    print("    files    %d in the denominator, %d carrying a gap"
          % (len({p for p, _ in lines}),
             len({p for p, _ in uncovered_lines} | {b[0] for b in uncovered_branches})))
    print()

    per_file = collections.defaultdict(lambda: [0, 0])
    for path, _ in uncovered_lines:
        per_file[path][0] += 1
    for key in uncovered_branches:
        per_file[key[0]][1] += 1

    print("    %-64s %6s %9s" % ("file", "lines", "outcomes"))
    for path in sorted(per_file, key=lambda p: (-sum(per_file[p]), p)):
        count = per_file[path]
        print("    %-64s %6d %9d" % (path, count[0], count[1]))

    if multiform:
        print()
        print("    %d line(s) compile to more than one branch form; an uncovered" % len(multiform))
        print("    outcome on one of these is uncovered in that form only:")
        for path, number, counts in multiform:
            gaps = sorted((b[2], b[3]) for b in uncovered_branches if b[0] == path and b[1] == number)
            marked = ""
            if gaps:
                marked = "  <- uncovered: " + ", ".join("form %d ordinal %d" % g for g in gaps)
            spread = ", ".join("%d branches in %d configuration(s)" % (n, c)
                               for n, c in sorted(collections.Counter(counts.values()).items()))
            print("        %s:%d  %s%s" % (path, number, spread, marked))

    return 0


if __name__ == "__main__":
    sys.exit(main())
